            FfiConverterOptionalString.INSTANCE.Write(value.RoomName, stream);
            FfiConverterOptionalString.INSTANCE.Write(value.ParticipantName, stream);
            FfiConverterOptionalString.INSTANCE.Write(value.ParticipantIdentity, stream);
            FfiConverterOptionalString.INSTANCE.Write(value.ParticipantMetadata, stream);
            FfiConverterOptionalDictionaryStringString.INSTANCE.Write(value.ParticipantAttributes, stream);
            FfiConverterOptionalString.INSTANCE.Write(value.AgentName, stream);
            FfiConverterOptionalString.INSTANCE.Write(value.AgentMetadata, stream);
            FfiConverterOptionalString.INSTANCE.Write(value.AgentDeployment, stream);
    }
}



