public class TokenSourceException: UniffiException {
    TokenSourceException() : base() {}
    TokenSourceException(String @Message) : base(@Message) {}

    // Each variant is a nested class
    
    
    public class Request : TokenSourceException {
        // Members
        public string @message;

        // Constructor
        public Request(
                string @message) : base(
                "@message" + "=" + @message) {

            this.@message = @message;
        }
    }
    
    
    public class Server : TokenSourceException {
        // Members
        public ushort @status;
        public string @body;

        // Constructor
        public Server(
                ushort @status, 
                string @body) : base(
                "@status" + "=" + @status+ ", " +
                "@body" + "=" + @body) {

            this.@status = @status;

            this.@body = @body;
        }
    }
    
    public class ErrorA : TokenSourceException {
        public ErrorA() : base() {}
    }
    
    
    public class ErrorB : TokenSourceException {
        public ErrorB() : base() {}
    }
    
    

    
}

class FfiConverterTypeTokenSourceError : FfiConverterRustBuffer<TokenSourceException>, CallStatusErrorHandler<TokenSourceException> {
    public static FfiConverterTypeTokenSourceError INSTANCE = new FfiConverterTypeTokenSourceError();

    public override TokenSourceException Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new TokenSourceException.Request(
                    FfiConverterString.INSTANCE.Read(stream));
            case 2:
                return new TokenSourceException.Server(
                    FfiConverterUInt16.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream));
            case 3:
                return new TokenSourceException.ErrorA();
            case 4:
                return new TokenSourceException.ErrorB();
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeTokenSourceError.Read()", value));
        }
    }

    public override int AllocationSize(TokenSourceException value) {
        switch (value) {

            case TokenSourceException.Request variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@message);

            case TokenSourceException.Server variant_value:
                return 4
                    + FfiConverterUInt16.INSTANCE.AllocationSize(variant_value.@status)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@body);

            case TokenSourceException.ErrorA variant_value:
                return 4;

            case TokenSourceException.ErrorB variant_value:
                return 4;
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeTokenSourceError.AllocationSize()", value));
        }
    }

    public override void Write(TokenSourceException value, BigEndianStream stream) {
        switch (value) {
            case TokenSourceException.Request variant_value:
                stream.WriteInt(1);
                FfiConverterString.INSTANCE.Write(variant_value.@message, stream);
                break;
            case TokenSourceException.Server variant_value:
                stream.WriteInt(2);
                FfiConverterUInt16.INSTANCE.Write(variant_value.@status, stream);
                FfiConverterString.INSTANCE.Write(variant_value.@body, stream);
                break;
            case TokenSourceException.ErrorA variant_value:
                stream.WriteInt(3);
                break;
            case TokenSourceException.ErrorB variant_value:
                stream.WriteInt(4);
                break;
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeTokenSourceError.Write()", value));
        }
    }
}




class FfiConverterOptionalString: FfiConverterRustBuffer<string?> {
    public static FfiConverterOptionalString INSTANCE = new FfiConverterOptionalString();

    public override string? Read(BigEndianStream stream) {
        if (stream.ReadByte() == 0) {
            return null;
        }
        return FfiConverterString.INSTANCE.Read(stream);
    }

    public override int AllocationSize(string? value) {
        if (value == null) {
            return 1;
        } else {
            return 1 + FfiConverterString.INSTANCE.AllocationSize((string)value);
        }
    }

    public override void Write(string? value, BigEndianStream stream) {
        if (value == null) {
            stream.WriteByte(0);
        } else {
            stream.WriteByte(1);
            FfiConverterString.INSTANCE.Write((string)value, stream);
        }
    }
}




